/**
 * Route Search Engine — Fuzzy search over the route registry.
 *
 * Scoring system (higher = better match):
 *   100  Exact label match
 *    90  Label starts with query
 *    80  Fuzzy label match (high similarity)
 *    70  Exact keyword match
 *    60  Substring in label
 *    55  Fuzzy keyword match
 *    50  Substring in keyword
 *    40  All query words found in label
 *    35  Fuzzy description match
 *    30  Substring in description
 *    25  Triggered-from match
 *    20  Substring in path
 *    15  Fuzzy path match
 *
 * Fuzzy matching uses bigram similarity (Dice coefficient) which handles:
 *   - Typos: "workfow" → "workflow"
 *   - Transpositions: "feidl" → "field"
 *   - Missing chars: "validtion" → "validation"
 *   - Extra chars: "settingss" → "settings"
 */

import {
  registry,
  type IndexEntry,
  type EntryType,
  CATEGORIES,
} from './route-registry';

// ─── Types ───────────────────────────────────────────────────────────

export interface SearchResult {
  entry: IndexEntry;
  score: number;
  matchedField: 'label' | 'keyword' | 'description' | 'path';
  highlights: { field: string; indices: [number, number][] }[];
}

export interface GroupedSearchResults {
  category: string;
  results: SearchResult[];
}

export interface SearchOptions {
  types?: EntryType[];
  categories?: string[];
  maxResults?: number;
  adminOnly?: boolean;
  /**
   * Registry to search over. Defaults to the English module registry. Pass a
   * localized copy (see `localizeRegistry`) so matching, scoring and display all
   * run on the same translated strings.
   */
  registry?: IndexEntry[];
}

// ─── Fuzzy Matching ──────────────────────────────────────────────────

/** Generate character bigrams from a string */
function bigrams(str: string): Set<string> {
  const result = new Set<string>();
  for (let i = 0; i < str.length - 1; i++) {
    result.add(str[i] + str[i + 1]);
  }
  return result;
}

/**
 * Dice coefficient (bigram similarity) between two strings.
 * Returns 0..1 where 1 = identical, 0 = no similarity.
 * Handles typos, transpositions, missing/extra characters well.
 */
function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) {
    // For single-char strings, fall back to simple equality
    return a === b ? 1 : 0;
  }

  const bigramsA = bigrams(a);
  const bigramsB = bigrams(b);

  let intersection = 0;
  for (const bg of bigramsA) {
    if (bigramsB.has(bg)) intersection++;
  }

  return (2 * intersection) / (bigramsA.size + bigramsB.size);
}

/**
 * Fuzzy match score: checks if query fuzzy-matches within text.
 * Returns 0..1 score. Checks both full-string similarity and
 * sliding-window matching for substring-like fuzzy matches.
 */
function fuzzyScore(query: string, text: string): number {
  if (text.includes(query)) return 1; // exact substring = perfect

  // Full string similarity
  const fullScore = diceCoefficient(query, text);

  // Word-level matching: check each word in text
  const textWords = text.split(/[\s\-_/]+/);
  let bestWordScore = 0;
  for (const word of textWords) {
    if (word.length === 0) continue;
    const wordScore = diceCoefficient(query, word);
    if (wordScore > bestWordScore) bestWordScore = wordScore;
  }

  // Sliding window: check query against text windows of similar length
  let bestWindowScore = 0;
  const windowLen = query.length;
  if (text.length >= windowLen) {
    for (let i = 0; i <= text.length - windowLen; i++) {
      const window = text.substring(i, i + windowLen);
      const ws = diceCoefficient(query, window);
      if (ws > bestWindowScore) bestWindowScore = ws;
    }
  }

  return Math.max(fullScore, bestWordScore, bestWindowScore);
}

/**
 * Multi-word fuzzy: for queries like "field valid", check if each word
 * fuzzy-matches somewhere in the text.
 */
function multiWordFuzzyScore(queryWords: string[], text: string): number {
  if (queryWords.length <= 1) return 0;

  const textWords = text.split(/[\s\-_/]+/);
  let totalScore = 0;
  let matchedWords = 0;

  for (const qw of queryWords) {
    let bestMatch = 0;
    // Check against each text word
    for (const tw of textWords) {
      const score = diceCoefficient(qw, tw);
      if (score > bestMatch) bestMatch = score;
    }
    // Also check substring
    if (text.includes(qw)) bestMatch = 1;

    if (bestMatch >= 0.5) {
      matchedWords++;
      totalScore += bestMatch;
    }
  }

  // All query words must match with reasonable score
  if (matchedWords < queryWords.length) return 0;
  return totalScore / queryWords.length;
}

// ─── Scoring Thresholds ──────────────────────────────────────────────

/** Minimum fuzzy score to consider a match (filters noise) */
const FUZZY_THRESHOLD = 0.45;

// Score tiers (higher = better match priority)
const SCORE_EXACT_LABEL = 100;
const SCORE_STARTS_WITH_LABEL = 90;
const SCORE_FUZZY_LABEL = 80;          // scaled by similarity
const SCORE_EXACT_KEYWORD = 70;
const SCORE_CONTAINS_LABEL = 60;
const SCORE_FUZZY_KEYWORD = 55;        // scaled by similarity
const SCORE_CONTAINS_KEYWORD = 50;
const SCORE_MULTI_WORD_LABEL = 40;     // scaled by similarity
const SCORE_FUZZY_DESCRIPTION = 35;    // scaled by similarity
const SCORE_CONTAINS_DESCRIPTION = 30;
const SCORE_TRIGGERED_FROM = 25;
const SCORE_CONTAINS_PATH = 20;
const SCORE_FUZZY_PATH = 15;           // scaled by similarity

// ─── Search Functions ────────────────────────────────────────────────

/**
 * Search the registry with a query string.
 * Supports exact, substring, and fuzzy matching with typo tolerance.
 */
export function search(query: string, options: SearchOptions = {}): SearchResult[] {
  if (!query || query.trim().length === 0) {
    return [];
  }

  const normalizedQuery = query.toLowerCase().trim();
  const queryWords = normalizedQuery.split(/\s+/);
  const results: SearchResult[] = [];

  const source = options.registry ?? registry;
  for (const entry of source) {
    if (options.types && options.types.length > 0 && !options.types.includes(entry.type)) {
      continue;
    }
    if (options.categories && options.categories.length > 0 && !options.categories.includes(entry.category)) {
      continue;
    }

    const result = scoreEntry(entry, normalizedQuery, queryWords);
    if (result) {
      results.push(result);
    }
  }

  results.sort((a, b) => b.score - a.score);

  if (options.maxResults && options.maxResults > 0) {
    return results.slice(0, options.maxResults);
  }

  return results;
}

/**
 * Search and group results by category.
 */
export function searchGrouped(query: string, options: SearchOptions = {}): GroupedSearchResults[] {
  const results = search(query, options);
  const groups = new Map<string, SearchResult[]>();

  for (const result of results) {
    const cat = result.entry.category;
    if (!groups.has(cat)) {
      groups.set(cat, []);
    }
    groups.get(cat)!.push(result);
  }

  const grouped: GroupedSearchResults[] = [];
  for (const category of CATEGORIES) {
    const categoryResults = groups.get(category);
    if (categoryResults && categoryResults.length > 0) {
      grouped.push({ category, results: categoryResults });
    }
  }

  return grouped;
}

/**
 * Quick search for Cmd+K modal.
 */
export function quickSearch(query: string, limit = 8): SearchResult[] {
  return search(query, { maxResults: limit });
}

// ─── Internal Scoring ────────────────────────────────────────────────

function scoreEntry(
  entry: IndexEntry,
  normalizedQuery: string,
  queryWords: string[],
): SearchResult | null {
  let bestScore = 0;
  let matchedField: SearchResult['matchedField'] = 'label';
  const highlights: SearchResult['highlights'] = [];

  const label = entry.label.toLowerCase();
  const description = entry.description.toLowerCase();
  const path = (entry.path || '').toLowerCase();
  const keywords = entry.keywords.map((k) => k.toLowerCase());

  // ── 1. Label matching (highest priority) ──

  if (label === normalizedQuery) {
    bestScore = SCORE_EXACT_LABEL;
    matchedField = 'label';
    highlights.push({ field: 'label', indices: [[0, label.length]] });
  } else if (label.startsWith(normalizedQuery)) {
    bestScore = SCORE_STARTS_WITH_LABEL;
    matchedField = 'label';
    highlights.push({ field: 'label', indices: [[0, normalizedQuery.length]] });
  } else if (label.includes(normalizedQuery)) {
    const idx = label.indexOf(normalizedQuery);
    bestScore = SCORE_CONTAINS_LABEL;
    matchedField = 'label';
    highlights.push({ field: 'label', indices: [[idx, idx + normalizedQuery.length]] });
  }

  // Multi-word matching on label: "field valid" matches "Field Validation"
  if (queryWords.length > 1) {
    const mwScore = multiWordFuzzyScore(queryWords, label);
    const score = SCORE_MULTI_WORD_LABEL + mwScore * 15; // 40..55
    if (mwScore >= FUZZY_THRESHOLD && score > bestScore) {
      bestScore = score;
      matchedField = 'label';
    }
  }

  // Fuzzy label match: "workfow" → "workflow"
  if (bestScore < SCORE_FUZZY_LABEL) {
    const fs = fuzzyScore(normalizedQuery, label);
    const score = SCORE_FUZZY_LABEL * fs; // 0..80 scaled
    if (fs >= FUZZY_THRESHOLD && score > bestScore) {
      bestScore = score;
      matchedField = 'label';
    }
  }

  // ── 2. Keyword matching ──

  for (const keyword of keywords) {
    if (keyword === normalizedQuery) {
      if (SCORE_EXACT_KEYWORD > bestScore) {
        bestScore = SCORE_EXACT_KEYWORD;
        matchedField = 'keyword';
      }
    } else if (keyword.includes(normalizedQuery)) {
      if (SCORE_CONTAINS_KEYWORD > bestScore) {
        bestScore = SCORE_CONTAINS_KEYWORD;
        matchedField = 'keyword';
      }
    } else {
      // Fuzzy keyword match
      const fs = fuzzyScore(normalizedQuery, keyword);
      const score = SCORE_FUZZY_KEYWORD * fs; // 0..55 scaled
      if (fs >= FUZZY_THRESHOLD && score > bestScore) {
        bestScore = score;
        matchedField = 'keyword';
      }
    }
  }

  // Multi-word against keywords
  if (queryWords.length > 1) {
    const allKeywords = keywords.join(' ');
    const mwScore = multiWordFuzzyScore(queryWords, allKeywords);
    const score = SCORE_CONTAINS_KEYWORD + mwScore * 10; // 50..60
    if (mwScore >= FUZZY_THRESHOLD && score > bestScore) {
      bestScore = score;
      matchedField = 'keyword';
    }
  }

  // ── 3. Description matching ──

  if (description.includes(normalizedQuery)) {
    if (SCORE_CONTAINS_DESCRIPTION > bestScore) {
      bestScore = SCORE_CONTAINS_DESCRIPTION;
      matchedField = 'description';
      const idx = description.indexOf(normalizedQuery);
      highlights.push({ field: 'description', indices: [[idx, idx + normalizedQuery.length]] });
    }
  } else if (queryWords.length > 1) {
    const mwScore = multiWordFuzzyScore(queryWords, description);
    const score = SCORE_CONTAINS_DESCRIPTION + mwScore * 8;
    if (mwScore >= FUZZY_THRESHOLD && score > bestScore) {
      bestScore = score;
      matchedField = 'description';
    }
  } else {
    const fs = fuzzyScore(normalizedQuery, description);
    const score = SCORE_FUZZY_DESCRIPTION * fs;
    if (fs >= FUZZY_THRESHOLD && score > bestScore) {
      bestScore = score;
      matchedField = 'description';
    }
  }

  // ── 4. Triggered-from matching ──

  if (entry.triggeredFrom) {
    const triggered = entry.triggeredFrom.toLowerCase();
    if (triggered.includes(normalizedQuery)) {
      if (SCORE_TRIGGERED_FROM > bestScore) {
        bestScore = SCORE_TRIGGERED_FROM;
        matchedField = 'description';
      }
    }
  }

  // ── 5. Path matching ──

  if (path) {
    if (path.includes(normalizedQuery)) {
      if (SCORE_CONTAINS_PATH > bestScore) {
        bestScore = SCORE_CONTAINS_PATH;
        matchedField = 'path';
        const idx = path.indexOf(normalizedQuery);
        highlights.push({ field: 'path', indices: [[idx, idx + normalizedQuery.length]] });
      }
    } else {
      const fs = fuzzyScore(normalizedQuery, path);
      const score = SCORE_FUZZY_PATH * fs;
      if (fs >= FUZZY_THRESHOLD && score > bestScore) {
        bestScore = score;
        matchedField = 'path';
      }
    }
  }

  if (bestScore === 0) {
    return null;
  }

  return { entry, score: bestScore, matchedField, highlights };
}

// ─── Filter Helpers ──────────────────────────────────────────────────

/** Get all entries, optionally filtered by type */
export function getAllEntries(options: SearchOptions = {}): IndexEntry[] {
  let entries = [...(options.registry ?? registry)];

  if (options.types && options.types.length > 0) {
    entries = entries.filter((e) => options.types!.includes(e.type));
  }

  if (options.categories && options.categories.length > 0) {
    entries = entries.filter((e) => options.categories!.includes(e.category));
  }

  return entries;
}
