/**
 * Route Registry — Central catalog of every navigable page and in-page feature in DocBits.
 * Used by the /sitemap index page and Cmd+K quick search.
 */

// ─── Types ───────────────────────────────────────────────────────────

export type EntryType = 'page' | 'dialog' | 'sidebar' | 'panel' | 'menu' | 'action';

/**
 * paramResolver: Tells the UI which param needs a picker and what kind.
 * - 'doc_type': shows a document type selector dropdown
 * - 'doc_id': shows a document picker (dashboard docs + paste ID)
 * - 'deep_link': navigate to page and auto-open dialog/sidebar via ?open= query param
 * - 'deep_link_doc': pick a document, then deep-link to page with ?open=X&doc_id=Y
 */
export type ParamResolverType = 'doc_type' | 'doc_id' | 'deep_link' | 'deep_link_doc';

export interface IndexEntry {
  id: string;
  type: EntryType;
  path?: string;
  label: string;
  description: string;
  category: string;
  subcategory?: string;
  icon?: string;
  keywords: string[];
  triggeredFrom?: string;
  requiresAdmin: boolean;
  requiresFeatureFlag?: string;
  /**
   * DOCB-14282: this entry is behind a per-role menu tab grant. The value is
   * the `feature_key` from `utils/analytics-access`'s registry. Consumers
   * (the command palette) must hide the entry from a user who may not see the
   * tab — offering a shortcut to a page that redirects is worse than not
   * offering it.
   */
  requiresFeatureAccess?: string;
  params?: { name: string; description: string }[];
  /** Which param resolver to use when this entry has dynamic params */
  paramResolver?: ParamResolverType;
  /** Which path param(s) the resolver fills (e.g., 'type' or 'doc_type') */
  paramResolverTarget?: string;
  /** For deep_link / deep_link_doc: the host page path to navigate to */
  deepLinkPath?: string;
  /** For deep_link / deep_link_doc: the ?open= query param value */
  deepLinkAction?: string;
  /** For doc_id resolver: filter dashboard docs to these statuses only */
  statusFilter?: string[];
}

