// ─── Utility Functions ───────────────────────────────────────────────

/** Get all entries in a specific category */
export function getByCategory(category: string): IndexEntry[] {
  return registry.filter((e) => e.category === category);
}

/** Get all entries of a specific type */
export function getByType(type: EntryType): IndexEntry[] {
  return registry.filter((e) => e.type === type);
}

/** Get all unique categories that have entries */
export function getActiveCategories(): string[] {
  const cats = new Set(registry.map((e) => e.category));
  return CATEGORIES.filter((c) => cats.has(c));
}

/** Get entries grouped by category */
export function getGroupedByCategory(): Map<string, IndexEntry[]> {
  const groups = new Map<string, IndexEntry[]>();
  for (const category of CATEGORIES) {
    const entries = getByCategory(category);
    if (entries.length > 0) {
      groups.set(category, entries);
    }
  }
  return groups;
}

/** Count entries by type */
export function getTypeCounts(): Record<EntryType, number> {
  const counts: Record<string, number> = {};
  for (const entry of registry) {
    counts[entry.type] = (counts[entry.type] || 0) + 1;
  }
  return counts as Record<EntryType, number>;
}

/** Get a single entry by ID */
export function getById(id: string): IndexEntry | undefined {
  return registry.find((e) => e.id === id);
}

// ─── i18n helpers ────────────────────────────────────────────────────
// Labels, descriptions and categories are authored in English in this file and
// translated via Tolgee. Keys are derived from the entry id / category text, so
// the registry objects above never need to carry key fields. The English string
// is always passed as the fallback, so a missing key never surfaces a raw key.

/** Translate function shape — matches Tolgee's `t` and `useTranslate().t`. */
export type TranslateFn = (key: string, fallback: string) => string;

function toKeySegment(text: string): string {
  return text
    .replace(/[^a-zA-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toLowerCase();
}

/** Tolgee key for an entry's label, e.g. `analytics-dashboard` → `gsearch_analytics_dashboard_label`. */
export function entryLabelKey(id: string): string {
  return `gsearch_${toKeySegment(id)}_label`;
}

/** Tolgee key for an entry's description. */
export function entryDescriptionKey(id: string): string {
  return `gsearch_${toKeySegment(id)}_desc`;
}

/** Tolgee key for a category, e.g. `Settings — Document Config` → `gsearch_cat_settings_document_config`. */
export function categoryKey(category: string): string {
  return `gsearch_cat_${toKeySegment(category)}`;
}

/**
 * Resolve a category's display label. The English category string stays the
 * canonical grouping/identity key (see `localizeRegistry`); this only translates
 * what the user sees.
 */
export function translateCategory(category: string, t: TranslateFn): string {
  return t(categoryKey(category), category);
}

/**
 * Return a copy of the registry with `label` and `description` resolved through
 * `t`. `category` is left untouched on purpose — it is the grouping key matched
 * against CATEGORIES; translate it for display with `translateCategory`.
 */
export function localizeRegistry(t: TranslateFn): IndexEntry[] {
  return registry.map((entry) => ({
    ...entry,
    label: t(entryLabelKey(entry.id), entry.label),
    description: t(entryDescriptionKey(entry.id), entry.description),
  }));
}
